(function(){document.addEventListener(`DOMContentLoaded`,()=>{document.addEventListener(`joomla-dialog:open`,e=>{if(e.target&&e.target.classList.contains(`preview-certificate-dialog`)){let t=e.target.JoomlaDialogTrigger.closest(`tr`);if(t){let e=t.querySelector(`input.form-check-input`);e&&e.checked&&e.click()}}})})})();